function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'StatisticsTracker') return 'The first operation must be StatisticsTracker.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls are allowed.';
  let stored = 0;
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    if (op === 'addNumber') {
      const number = args[i][0];
      if (args[i].length !== 1 || !Number.isInteger(number) || number < 1 || number > 1000000000) return 'addNumber takes one number between 1 and 10^9.';
      stored++;
    } else if (op === 'removeFirstAddedNumber' || op === 'getMean' || op === 'getMedian' || op === 'getMode') {
      if (stored === 0) return op + ' is only called while at least one number is stored.';
      if (op === 'removeFirstAddedNumber') stored--;
    } else {
      return 'Unknown operation ' + op + '.';
    }
  }
  return null;
}

