class StatisticsTracker {
  constructor() {
    this.queue = [];
    this.head = 0;
    this.sum = 0;
    this.count = new Map();
    this.sorted = { items: [], before: (a, b) => a < b };
    this.ranking = { items: [], before: (a, b) => a[0] > b[0] || (a[0] === b[0] && a[1] < b[1]) };
  }

  addNumber(number) {
    this.queue.push(number);
    this.sum += number;
    this.insert(this.sorted, number);
    this.changeCount(number, 1);
  }

  removeFirstAddedNumber() {
    const number = this.queue[this.head];
    this.head++;
    this.sum -= number;
    this.erase(this.sorted, number);
    this.changeCount(number, -1);
  }

  getMean() {
    return Math.floor(this.sum / this.sorted.items.length);
  }

  getMedian() {
    const items = this.sorted.items;
    return items[Math.floor(items.length / 2)];
  }

  getMode() {
    return this.ranking.items[0][1];
  }

  changeCount(number, delta) {
    const old = this.count.get(number) ?? 0;
    const now = old + delta;
    if (old > 0) this.erase(this.ranking, [old, number]);
    if (now > 0) this.insert(this.ranking, [now, number]);
    this.count.set(number, now);
  }

  insert(list, item) {
    list.items.splice(this.position(list, item), 0, item);
  }

  erase(list, item) {
    list.items.splice(this.position(list, item), 1);
  }

  position(list, item) {
    let low = 0;
    let high = list.items.length;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (list.before(list.items[mid], item)) low = mid + 1;
      else high = mid;
    }
    return low;
  }
}

