class StatisticsTracker {
  // Keep the numbers in the order they arrived and recompute every statistic from scratch.
  constructor() {
    this.numbers = [];
  }
  addNumber(number) {
    this.numbers.push(number);
  }
  removeFirstAddedNumber() {
    this.numbers.shift();
  }
  getMean() {
    return Math.floor(this.numbers.reduce((a, b) => a + b, 0) / this.numbers.length);
  }
  getMedian() {
    const ordered = [...this.numbers].sort((a, b) => a - b);
    return ordered[Math.floor(ordered.length / 2)];
  }
  getMode() {
    let best = null;
    let bestCount = 0;
    for (const v of this.numbers) {
      const c = this.numbers.filter(x => x === v).length;
      if (c > bestCount || (c === bestCount && v < best)) {
        best = v;
        bestCount = c;
      }
    }
    return best;
  }
}

