function generate(rand, size) {
  const large = size === 'large';
  const total = large ? 500 : 2 + Math.floor(rand() * 18);
  // Small value ranges make repeated values (and mode ties) common; sometimes use the full range.
  const spread = rand() < 0.25 ? 1000000000 : large ? 1 + Math.floor(rand() * 60) : 1 + Math.floor(rand() * 6);
  const addShare = large ? 0.3 + rand() * 0.3 : 0.45;
  const operations = ['StatisticsTracker'];
  const args = [[]];
  let stored = 0;
  while (operations.length < total) {
    const r = rand();
    if (stored === 0 || r < addShare) {
      operations.push('addNumber');
      args.push([1 + Math.floor(rand() * spread)]);
      stored++;
    } else if (r < addShare + 0.18) {
      operations.push('removeFirstAddedNumber');
      args.push([]);
      stored--;
    } else {
      operations.push(['getMean', 'getMedian', 'getMode'][Math.floor(rand() * 3)]);
      args.push([]);
    }
  }
  return [operations, args];
}
